// Package S3: the conformance checker against the public test suite (testsuite/faelle.json) and
// the command line `hpro-check` (text and JSON output, exit codes of part 1, section 4.5).
// The suite is generated by scripts/s3-testsuite.mjs; this test only reads the committed files.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { promisify } from 'node:util';
import { certificatesFromPem, checkConformance, validateAgainstSchema, type Catalog, type ConformanceReport } from '../src/index.js';
import { REPO_ROOT } from './helpers.js';

interface Case {
  id: string;
  art: 'gut' | 'schlecht';
  datei: string;
  regeln: string[];
  erwarteteBefunde: string[];
  erwartetesUrteil: Record<string, string>;
  vertrauensanker?: string;
  redigiert?: string[];
}
interface Suite {
  pruefzeitpunktSignaturen: string;
  fehlendeMittel: Record<string, string>;
  faelle: Case[];
}

const SUITE_DIR = resolve(REPO_ROOT, 'testsuite');
const CLI = resolve(REPO_ROOT, 'kern/build/bin/hpro-check.js');
const json = async <T>(path: string): Promise<T> => JSON.parse(await readFile(path, 'utf8')) as T;

const catalog = await json<Catalog>(resolve(REPO_ROOT, 'docs/spezifikation/01-regelkatalog.json'));
const schema = await json<Record<string, unknown>>(resolve(REPO_ROOT, 'docs/spezifikation/schema/konformitaetsbericht.schema.json'));
const functions = (await json<{ functions: Array<{ name: string }> }>(resolve(REPO_ROOT, 'docs/spezifikation/03-funktionen.json'))).functions.map((f) => f.name);
const suite = await json<Suite>(resolve(SUITE_DIR, 'faelle.json'));

async function run(c: Case): Promise<ConformanceReport> {
  const trustAnchors = c.vertrauensanker ? certificatesFromPem(await readFile(resolve(SUITE_DIR, c.vertrauensanker), 'utf8')) : [];
  return checkConformance(await readFile(resolve(SUITE_DIR, c.datei)), catalog, {
    fileName: c.datei,
    trustAnchors,
    validationTime: suite.pruefzeitpunktSignaturen,
    redactedTerms: c.redigiert ?? [],
    supportedFunctions: functions,
  });
}

test('the suite has at least 15 rules with a good and a bad case', () => {
  const good = new Set(suite.faelle.filter((c) => c.art === 'gut').flatMap((c) => c.regeln));
  const bad = new Set(suite.faelle.filter((c) => c.art === 'schlecht').flatMap((c) => c.regeln));
  const both = [...good].filter((id) => bad.has(id));
  assert.ok(both.length >= 15, `only ${both.length} rules with good and bad case`);
  const known = new Set(catalog.rules.map((r) => r.id));
  for (const c of suite.faelle) for (const id of [...c.regeln, ...c.erwarteteBefunde]) assert.ok(known.has(id), `${c.id}: unknown rule ${id}`);
});

for (const c of suite.faelle) {
  test(`${c.art}: ${c.id}`, async () => {
    const report = await run(c);
    const found = [...new Set(report.results.map((r) => r.rule))].sort();
    assert.deepEqual(found, [...c.erwarteteBefunde].sort(), 'rules with findings');
    for (const [level, verdict] of Object.entries(c.erwartetesUrteil)) assert.equal(report.levels.verdict[level as keyof typeof report.levels.verdict], verdict, `verdict ${level}`);
    const notChecked = new Map(report.notChecked.map((n) => [n.rule, n]));
    for (const id of c.regeln) assert.ok(!notChecked.has(id), `${id} not checked: ${notChecked.get(id)?.detail ?? ''}`);
    if (c.art === 'schlecht') for (const id of c.regeln) assert.ok(found.includes(id), `target rule ${id} without finding`);
    else for (const id of c.regeln) assert.ok(!found.includes(id), `target rule ${id} with finding`);
    // Only missing means (no engine, no EPUB validator, no redaction list) or a failed precondition may leave rules unchecked.
    const fatal = report.results.some((r) => r.class === 'FATAL');
    if (!fatal) for (const n of report.notChecked) assert.ok(n.reason === 'fatal' || n.rule in suite.fehlendeMittel, `${n.rule} not checked (${n.reason})`);
    assert.deepEqual(validateAgainstSchema(report, schema), [], 'report schema');
  });
}

test('hpro-check: text and JSON output, exit codes (section 4.4/4.5)', async () => {
  const exec = async (args: string[]) => {
    try {
      const { stdout } = await promisify(execFile)(process.execPath, [CLI, ...args, '--no-epubcheck'], { maxBuffer: 16 * 1024 * 1024 });
      return { code: 0, stdout };
    } catch (err) {
      const e = err as { code?: number; stdout?: string };
      return { code: e.code ?? -1, stdout: e.stdout ?? '' };
    }
  };
  const doc = (id: string) => resolve(SUITE_DIR, `dokumente/${id}.hpro`);

  const bad = await exec([doc('schlecht-cont-016-manipuliert')]);
  assert.equal(bad.code, 1);
  assert.match(bad.stdout, /^FEHLER HPR-CONT-016 content\/index\.xhtml: Ressource content\/index\.xhtml: Hash stimmt nicht/m);
  assert.match(bad.stdout, /^Befunde: 0 fatal, 1 Fehler, 0 Warnungen, 0 Hinweise, \d+ nicht geprüft$/m);
  assert.match(bad.stdout, /^Stufe Basis: nicht bestanden$/m);

  const good = await exec([doc('gut-basis'), '--format', 'json']);
  assert.equal(good.code, 3, 'Basis is undetermined without browser engine');
  const report = JSON.parse(good.stdout) as ConformanceReport;
  assert.equal(report.results.length, 0);
  assert.equal(report.levels.verdict.Basis, 'unbestimmt');
  assert.deepEqual(validateAgainstSchema(report, schema), []);

  const fatal = await exec([doc('schlecht-cont-001-kein-zip')]);
  assert.equal(fatal.code, 1);
  assert.match(fatal.stdout, /^FATAL HPR-CONT-001 \(Container\): Die Datei ist kein lesbares ZIP-Archiv/m);

  const usage = await exec([]);
  assert.equal(usage.code, 2);
  const missing = await exec([doc('gibt-es-nicht')]);
  assert.equal(missing.code, 2);
});
